import { Component, createMemo, createSignal, For, onMount, Show } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { Dropdown, DropdownItem } from "#core/ui-next/components/dropdown.jsx";
import { Hotkeys } from "#core/ui-next/components/hotkeys.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { useScreenFlowContext } from "#core/ui-next/components/screen-flow.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SearchBar } from "#core/ui-next/components/search-bar.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { Tooltip, TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";
import { CreateGameHRule2 } from "#core/ui-next/screens/create-game/create-game-components.jsx";
import {
	CreateGameStage,
	CreateGameStageHeader,
	CreateGameStageMode,
} from "#core/ui-next/screens/create-game/create-game-stage.jsx";
import {
	MementoInfo,
	MementoSlotInfo,
	useMementoSelectModelContext,
} from "#core/ui-next/screens/create-game/memento-select-model.js";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { isMobile, ViewExperience } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import style from "./memento-select.scss?url";

// MARK: MEMENTO TEXT INFO

interface MementoTextInfoProps extends MementosUIData {
	class?: string;
	showFlavor?: boolean;
}

const MementoTextInfo: Component<MementoTextInfoProps> = (props) => {
	return (
		<div class={`flex-auto flex flex-col ${props.class ?? ""}`}>
			<div class="uppercase font-title font-black text-tertiary-1">
				<L10n.Compose text={props.mementoName} />
			</div>

			<CreateGameHRule2
				color="#646363"
				class="my-2"
			/>

			<L10n.Stylize
				class="create-game-markup"
				text={props.functionalTextDesc}
			/>
			<Show when={props.showFlavor}>
				<div class="flex-auto" />
				<CreateGameHRule2
					color="#646363"
					class="mb-2"
				/>

				<L10n.Stylize
					class="create-game-markup font-fit-shrink"
					text={props.flavorTextDesc}
				/>
			</Show>
		</div>
	);
};

// MARK: MEMENTO CARD

interface MementoTextInfoProps extends MementosUIData {
	isEquipped?: boolean;
	isLocked?: boolean;
}

const MementoCard: Component<MementoTextInfoProps> = (props) => {
	return (
		<div
			class={`flex flex-row relative m-3 p-2 img-unit-panelbox memento-select ${props.isLocked ? "memento-select-locked" : ""}`}
		>
			<div
				class="flex mr-1 overflow-hidden absolute inset-0 items-center"
				classList={{ "w-48": !isMobile(), "w-44": isMobile() }}
			>
				<Icon
					class={`absolute -left-16 opacity-5 ${isMobile() ? "size-60" : "size-64"}`}
					name={`url('blp:${props.mementoIcon ?? ""}')`}
					isUrl={true}
				/>
				<div class="absolute left-2\.5">
					<Icon
						class={isMobile() ? "size-28" : "size-32"}
						name={`url('blp:${props.mementoIcon ?? ""}')`}
						isUrl={true}
					/>
				</div>
			</div>
			<MementoTextInfo
				{...props}
				class={`mb-4 mt-7 mr-5 ${isMobile() ? "ml-32" : "ml-40"}`}
			/>

			<div class="memento-select-corner-filigree top-left" />
			<div class="memento-select-corner-filigree top-right" />
			<div class="memento-select-corner-filigree bottom-left" />
			<div class="memento-select-corner-filigree bottom-right" />

			<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />

			<div class="absolute -left-2 top-4">
				<Show when={props.isNewAndUnseenByPlayer && !props.isEquipped && !props.isLocked}>
					<div
						class="flex items-center justify-center pb-2 font-semibold"
						style={{
							"border-image-source": `url('blp:tag_new.png')`,
							"border-image-slice": "1 20 1 8 fill",
							"border-image-repeat": "stretch",
							"border-width": "1px 20px 1px 8px",
							"border-style": "solid",
							"min-width": Layout.pixels(54),
							height: Layout.pixels(43),
						}}
					>
						<L10n.Stylize
							class="uppercase text-sm font-body"
							text="LOC_UI_CREATE_GAME_NEW"
						/>
					</div>
				</Show>
				<Show when={props.isEquipped && !props.isLocked}>
					<div class="relative flex">
						<div
							class="flex flex-row items-start justify-start relative"
							style={{
								"border-image-source": `url('blp:tag_equipped.png')`,
								"border-image-slice": "1 6 1 1 fill",
								"border-image-repeat": "stretch",
								width: Layout.pixels(54),
								height: Layout.pixels(43),
							}}
						>
							<div
								class="img-icon-checkmark size-8 absolute mt-0\.5 ml-0\.5"
								style={{
									// eslint-disable-next-line solid/style-prop
									"fxs-background-image-tint": "black",
								}}
							/>
						</div>
					</div>
				</Show>
				<Show when={props.isLocked}>
					<div class="img-tag-locked flex flex-row items-start justify-start">
						<div class="img-lock2 size-8 mt-0\.5 ml-0\.5" />
					</div>
				</Show>
			</div>
			{/* TODO Hiding favorite Icon as requested until implement https://firaxis.slack.com/archives/C08KT2445QV/p1769814234743609 
			<Icon
				class="size-13 absolute left-4 top-44"
				name='url("blp:fav_star_well.png")'
			/>
			<Show when={props.isFavorite}>
				<Icon
					class="size-11 m-1 absolute left-4 top-44"
					name='url("blp:fav_star_fill.png")'
				/>
			</Show> */}
		</div>
	);
};

// MARK: MEMENTO SLOT

interface MementoSlotProps {
	memento?: MementoInfo;
	isSelected: boolean;
	class?: string;
}

const MementoSlot: Component<MementoSlotProps> = (props) => {
	return (
		<div
			class={`flex items-center justify-center py-1 img-unit-panelbox relative group memento-select-slot ${props.class ?? ""}`}
		>
			<Icon
				name='url("blp:memento_slot-base.png")'
				class="absolute -top-4\.5 -left-4\.5 memento-select-slot-base opacity-60"
			/>
			<div
				class="flex absolute inset-0 memento-select-slot"
				style={{
					"background-image": `url('blp:shell_memento-maj-plus.png')`,
					"background-repeat": "no-repeat",
					"background-position": "center",
				}}
			/>
			<Icon
				name={`url('blp:${props.memento?.icon ?? ""}')`}
				isUrl={true}
				class="memento-select-slot-icon absolute"
			/>
			<Show when={props.isSelected}>
				<div class="img-rollover-highlight absolute inset-x-0 inset-y-0\.5 pointer-events-none" />
			</Show>
			<Show when={!props.isSelected}>
				<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
			</Show>
		</div>
	);
};

// MARK: MEMENTO SELECT

const MementoSelectComponent: Component = () => {
	const model = useMementoSelectModelContext();
	const flowContext = useScreenFlowContext();

	// TODO these should not be filtered by a string name
	// mementoTags seems to be defined in the C++
	const filterItems: string[][] = [
		["ALL", "LOC_LEGACIES_FILTER_ALL_ATTRIBUTES"],
		["CULTURAL", "LOC_ATTRIBUTE_CULTURAL"],
		["ECONOMIC", "LOC_ATTRIBUTE_ECONOMIC"],
		["SCIENTIFIC", "LOC_ATTRIBUTE_SCIENTIFIC"],
		["MILITARISTIC", "LOC_ATTRIBUTE_MILITARISTIC"],
		["EXPANSIONIST", "LOC_ATTRIBUTE_EXPANSIONIST"],
		["DIPLOMATIC", "LOC_ATTRIBUTE_POLITICAL"],
		["WILDCARD", "LOC_ATTRIBUTE_WILDCARD"],
	];

	const [selectedFilter, setSelectedFilter] = createSignal<string[]>(filterItems[0]);
	const [textFilter, setTextFilter] = createSignal<string>("");

	const isSmallScreen = useIsSmallScreen();
	const enableTextFilter = createMemo<boolean>(() => ViewExperience() == UIViewExperience.Desktop || isMobile());
	const showSearch = createMemo(
		() => (!isSmallScreen() || isMobile()) && enableTextFilter() && !IsControllerActive(),
	);

	const searchResults = createMemo(() => (textFilter() ? model.fulltextSearch(textFilter()) : new Set<string>()));

	const selectedFilterLower = createMemo(() => {
		const filter = selectedFilter()[0].toLowerCase();
		return filter === "all" ? null : filter;
	});

	const filteredMementos = createMemo(() => {
		const category = selectedFilterLower();
		const search = textFilter().toLowerCase();
		const textFilterEnabled = enableTextFilter();

		return model.mementos
			.filter((memento) => {
				//Filter category. if all/null pass, otherwise look for the tag
				const matchesCategory = !category || memento.mementoTags.toLowerCase().includes(category);

				//Filter Text. if it's not enabled or text is not present pass, otherwise search
				const matchesText = !textFilterEnabled || !search || searchResults().has(memento.mementoTypeId);

				return matchesCategory && matchesText;
			})
			.sort((a, b) => {
				// TODO Hiding favorite Icon as requested until implement https://firaxis.slack.com/archives/C08KT2445QV/p1769814234743609
				//Favorities on top
				// if (a.isFavorite !== b.isFavorite) {
				// 	return a.isFavorite ? -1 : 1;
				// }
				//Unlocked after
				if (a.displayType !== b.displayType) {
					return a.displayType === DisplayType.DISPLAY_UNLOCKED ? -1 : 1;
				}
				return 0;
			});
	});

	const numMementos = createMemo(() => filteredMementos().length);

	const slot1Memento = createMemo(() =>
		model.mementos.find((m) => m.mementoTypeId == model.slots[0]?.currentMemento.value),
	);
	const slot2Memento = createMemo(() =>
		model.mementos.find((m) => m.mementoTypeId == model.slots[1]?.currentMemento.value),
	);

	const areSlotsFull = createMemo(() => !!(slot1Memento() && slot2Memento()));

	const isAgeTransition = UI.isInGame();

	const audioControllerTrigger = useAudio("MementoSelect/MementoSlot/Activatable");

	function handleEquip(memento: MementosUIData) {
		if (memento.displayType == DisplayType.DISPLAY_UNLOCKED) {
			model.equipMemento(memento);
		}
	}

	// TODO: Find a more permament solution for hotseat. This is a temporary fix to hide mementos when in a hotseat game. This is being used because of the tight encapsulation of MementoSelectModelContext.Provider in age-transition-screen.tsx
	// Note: During age transition in hotseat, the mementos panel flickers once because of waitForLayout. However, waitForLayout is necessary to transition out of the background screen.
	onMount(() => {
		waitForLayout(() => {
			if (Configuration.getGame().isHotseat) {
				flowContext.activateNext();
			}
		});
	});

	const mementoSlotTooltipMobile = (slot: MementoSlotInfo, index: number) => {
		const isEmptySlot = slot.currentMemento.functionalDescription == "LOC_MEMENTO_NONE_DESCRIPTION";
		return (
			<Tooltip
				initialHPosition={TooltipHorizontalPosition.LEFT}
				initialVPosition={TooltipVerticalPosition.CENTER}
			>
				<Tooltip.Trigger>
					{
						<Activatable
							disableFocus={true}
							onActivate={() => model.setSelectedSlot(index)}
							hotkeyAction={slot.hotkey}
							class="relative"
						>
							<MementoSlot
								memento={slot.currentMemento}
								isSelected={model.selectedSlot() == index}
								class="mb-8"
							/>
							<NavHelp class="absolute bottom-4 right-6" />
						</Activatable>
					}
				</Tooltip.Trigger>
				<Tooltip.Content class="max-w-128">
					<Tooltip.Frame>
						<div class="items-center">
							<div class="font-title-base fxs-header uppercase self-center mb-4">
								<L10n.Compose text={slot.currentMemento.name ?? "LOC_UI_CREATE_GAME_EMPTY"} />
							</div>
							<Show when={slot.currentMemento.functionalDescription}>
								<CardFrame class={`${isEmptySlot ? `p-4` : `pt-4 px-4`} mb-4`}>
									<div>
										<L10n.Stylize
											text={
												isEmptySlot
													? Locale.compose(slot.currentMemento.functionalDescription!)
													: `[BLIST][LI] ${Locale.compose(slot.currentMemento.functionalDescription!)}[/LIST]`
											}
											class="create-game-markup"
										/>
									</div>
								</CardFrame>
							</Show>
							<Show when={slot.currentMemento.description}>
								<CardFrame class="p-4 mb-4">
									<div>
										<L10n.Stylize
											text={Locale.compose(slot.currentMemento.description!)}
											class="create-game-markup"
										/>
									</div>
								</CardFrame>
							</Show>
						</div>
					</Tooltip.Frame>
				</Tooltip.Content>
			</Tooltip>
		);
	};

	return (
		<CreateGameStage
			header={
				<CreateGameStageHeader
					showSteps={false}
					title="LOC_UI_CREATE_GAME_MEMENTO_SELECT"
					hideButtonText={isAgeTransition ? "LOC_UI_AGE_TRANSITION_VIEW_MAP" : undefined}
				/>
			}
			mode={isAgeTransition ? CreateGameStageMode.StageOnly : CreateGameStageMode.Full}
		>
			<Hotkeys
				hotkeys={[
					{
						hotkeyAction: "shell-action-2",
						navTrayText: "LOC_UI_FILTER_SORT_FILTERS",
					},
				]}
			/>
			<AudioContextProvider segment="MementoSelect">
				<div
					class="flex-auto font-title relative flex"
					classList={{ "flex-col": !isMobile(), "flex-row-reverse": isMobile() }}
					data-name="layout-center"
				>
					<div
						class="flex flex-row"
						classList={{ "mt-4 mb-2": !isMobile() }}
					>
						<div
							class="flex flex-row items-center justify-center -top-4"
							classList={{ "w-full absolute": !isMobile() }}
						>
							<Show when={!isMobile()}>
								<div class="memento-select-text-info overflow-hidden left">
									<Show when={slot1Memento()}>
										<MementoTextInfo
											{...slot1Memento()!}
											class="mr-5"
											showFlavor={true}
										/>
									</Show>
								</div>
							</Show>
							<div
								class="flex flex-col py-4"
								classList={{ "img-unit-panelbox": !isMobile() }}
							>
								<div
									class="flex justify-between px-2"
									classList={{ "flex-row": !isMobile(), "flex-col self-center": isMobile() }}
								>
									<For each={model.slots}>
										{(slot, index) => (
											<AudioContextProvider segment="MementoSlot">
												<Show
													when={!isMobile()}
													fallback={mementoSlotTooltipMobile(slot, index())}
												>
													<Tooltip.Text
														text={slot.currentMemento.name ?? "LOC_UI_CREATE_GAME_EMPTY"}
													>
														<Activatable
															disableFocus={true}
															onActivate={() => {
																const prevSelectedSlot = model.selectedSlot();
																model.setSelectedSlot(index());

																// Controller audio feedback support
																if (
																	IsControllerActive() &&
																	prevSelectedSlot !== index()
																) {
																	audioControllerTrigger("slot-select");
																}
															}}
															hotkeyAction={slot.hotkey}
															class="relative"
														>
															<MementoSlot
																memento={slot.currentMemento}
																isSelected={model.selectedSlot() == index()}
																class="mx-2"
															/>
															<NavHelp class="absolute bottom-4 right-6" />
														</Activatable>
													</Tooltip.Text>
												</Show>
											</AudioContextProvider>
										)}
									</For>
								</div>
								<Show
									when={isAgeTransition}
									fallback={
										<Button
											class="h-12 mx-4 mt-4"
											onActivate={() => flowContext.activatePrev()}
											autoFocus={areSlotsFull()}
										>
											<L10n.Compose text="LOC_UI_CREATE_GAME_CONFIRM_SELECTIONS" />
										</Button>
									}
								>
									<Button
										class={`create-game-setup-button ${isMobile() ? "h-12 mx-4 mt-4" : ""}`}
										onActivate={() => flowContext.activateNext()}
										autoFocus={areSlotsFull()}
									>
										<L10n.Compose text="LOC_GENERIC_CONTINUE" />
									</Button>
								</Show>
							</div>
							<Show when={!isMobile()}>
								<div class="memento-select-text-info overflow-hidden right">
									<Show when={slot2Memento()}>
										<MementoTextInfo
											{...slot2Memento()!}
											class="ml-5"
											showFlavor={true}
										/>
									</Show>
								</div>
							</Show>
						</div>
					</div>
					<Show when={isMobile()}>
						<div class="memento-select-divider-line relative" />
						<div class="memento-select-divider-gradient relative" />
					</Show>
					<div class="flex flex-col flex-auto memento-select-list-container">
						<div class="flex flex-row my-2 mt-48 justify-between memento-select-filter-bar">
							<Show when={showSearch()}>
								<SearchBar
									value={textFilter}
									setValue={setTextFilter}
									class="w-76"
								/>
							</Show>
							<div class="flex flex-row items-center justify-end">
								<L10n.Stylize
									text="LOC_UI_CREATE_GAME_MEMENTOS_NUM"
									args={[numMementos()]}
									class="ml-3 items-center justify-center font-body text-accent-2 uppercase"
								/>
								<AudioContextProvider segment="FilterDropdown">
									<Dropdown
										defaultValue={filterItems[0]}
										selectedItemTemplate={(item) => (
											<div class="mx-2 w-full font-fit-shrink font-body text-accent-2">
												<L10n.Compose
													text="LOC_UI_CREATE_GAME_FILTER_ITEM"
													args={[Locale.toUpper(Locale.compose(item[1]))]}
												/>
											</div>
										)}
										hotkey="shell-action-2"
										onItemSelected={(item) => setSelectedFilter(item)}
										class="memento-select-dropdown min-w-76"
										disableFocus={true}
									>
										<For each={filterItems}>
											{(item) => (
												<DropdownItem value={item}>
													{Locale.toUpper(Locale.compose(item[1]))}
												</DropdownItem>
											)}
										</For>
									</Dropdown>
								</AudioContextProvider>
							</div>
						</div>

						<div
							class="flex flex-auto relative"
							classList={{ "flex-col": !isMobile(), "flex-row-reverse": isMobile() }}
						>
							<Show when={!isMobile()}>
								<div class="memento-select-divider-gradient absolute top-2" />
								<div class="memento-select-divider-line my-2 relative" />
							</Show>
							<ScrollArea class={`flex-auto ${isMobile() ? "ml-1" : "ml-8"} mr-1\\.5 mb-0\\.5 relative`}>
								<SpatialSlot
									name="create-game-mementos-slot"
									class="flex flex-row flex-wrap"
									autoFocus={!areSlotsFull()}
								>
									<For each={filteredMementos()}>
										{(memento) => (
											<Tooltip>
												<AudioContextProvider
													segment="MementoArray"
													vars={{
														isEquipped: (
															slot1Memento() == memento || slot2Memento() == memento
														).toString(),
													}}
												>
													<Tooltip.Trigger>
														<Activatable
															onActivate={() => handleEquip(memento)}
															class="group"
															disableAudio={
																memento.displayType == DisplayType.DISPLAY_LOCKED
															}
														>
															<MementoCard
																{...memento}
																isEquipped={
																	slot1Memento() == memento ||
																	slot2Memento() == memento
																}
																isLocked={
																	memento.displayType == DisplayType.DISPLAY_LOCKED
																}
															/>
														</Activatable>
													</Tooltip.Trigger>
													<Show when={memento.displayType == DisplayType.DISPLAY_LOCKED}>
														<Tooltip.Content>
															<Tooltip.Frame
																class={"relative flex flex-col pb-1 max-w-128"}
															>
																<div class={"flex-auto p-3 img-base-ticket-bg"}>
																	<L10n.Stylize
																		text={memento.unlockReason}
																		class="relative"
																	/>
																</div>
															</Tooltip.Frame>
														</Tooltip.Content>
													</Show>
												</AudioContextProvider>
											</Tooltip>
										)}
									</For>
								</SpatialSlot>
							</ScrollArea>
						</div>
					</div>
				</div>
			</AudioContextProvider>
		</CreateGameStage>
	);
};

export const MementoSelect = ComponentRegistry.register({
	name: "memento-select",
	createInstance: MementoSelectComponent,
	styles: [style],
});
